src/topics/02-object-interface.ts<pre><code>// Arreglo tipado: solo admite strings
const skills: string[] = ['Bash', 'Counter', 'Healing'];

// Definición de una Interfaz (Contrato de Objeto)
interface Character {
    name: string;
    hp: number;
    skills: string[];
    hometown?: string; // Propiedad opcional (puede ser string o undefined)
}

// Creación de un objeto bajo el contrato de la interfaz
const strider: Character = {
    name: 'Strider',
    hp: 100,
    skills: ['Bash', 'Counter'],
};

// Asignación válida de la propiedad opcional
strider.hometown = 'Rivendell';

// Imprime el objeto formateado como tabla en la consola
console.table(strider);

export {};
</code></pre>

src/topics/03-functions.ts<pre><code>// 1. Función tradicional con tipado de argumentos y retorno
function addNumbers(a: number, b: number): number {
    return a + b;
}

// 2. Función flecha (Arrow function)
const addNumbersArrow = (a: number, b: number): string =&gt; {
    return `${a + b}`; // Retorna un string gracias a los backticks
};

// 3. Función con parámetros opcionales y valores por defecto
// REGLA: Los parámetros obligatorios van primero, luego los opcionales y por defecto
function multiply(firstNumber: number, secondNumber?: number, base: number = 2): number {
    return firstNumber * base;
}

const result1: number = addNumbers(1, 2);
const result2: string = addNumbersArrow(1, 2);
const multiplyResult: number = multiply(5); // secondNumber no se envía, base toma 2 -&gt; resultado: 10

console.log({ result1, result2, multiplyResult });

// 4. Funciones que reciben objetos tipados mediante interfaces
interface Character {
    name: string;
    hp: number;
    showHp: () =&gt; void; // Declaración de método sin retorno
}

const healCharacter = (character: Character, amount: number): void =&gt; {
    character.hp += amount;
};

const strider: Character = {
    name: 'Strider',
    hp: 50,
    showHp() {
        console.log(`Puntos de vida: ${this.hp}`);
    }
};

healCharacter(strider, 60);
strider.showHp(); // Imprime: Puntos de vida: 110

export {};
</code></pre>

src/topics/05-basic-destructuring.ts<pre><code>interface AudioPlayer {
    audioVolume: number;
    songDuration: number;
    song: string;
    details: Details;
}

interface Details {
    author: string;
    year: number;
}

const audioPlayer: AudioPlayer = {
    audioVolume: 90,
    songDuration: 36,
    song: 'Mess',
    details: {
        author: 'Ed Sheeran',
        year: 2015
    }
};

// 1. DESESTRUCTURACIÓN DE OBJETOS
// Extraemos propiedades directas y renombramos 'song' a 'anotherSong' para evitar colisiones:
const { song: anotherSong, songDuration: duration, details } = audioPlayer;

// Desestructuración anidada limpia a partir de la constante extraída:
const { author } = details;

console.log('Canción:', anotherSong);
console.log('Duración:', duration);
console.log('Autor:', author);

// 2. DESESTRUCTURACIÓN DE ARREGLOS
// En los arreglos la posición determina la asignación.
const dbz: string[] = ['Goku', 'Vegeta', 'Trunks'];

// Si solo nos interesa el tercer personaje, dejamos espacios vacíos con comas:
const [, , trunks = 'No encontrado'] = dbz;

console.log('Personaje 3:', trunks); // Trunks

export {};
</code></pre>

src/topics/08-classes.ts<pre><code>export class Person {
    constructor(
        public firstName: string,
        public lastName: string,
        private address: string = 'No Address'
    ) {}
}

// APLICACIÓN DE COMPOSICIÓN:
// En lugar de `class Hero extends Person`, inyectamos la persona en el constructor
export class Hero {
    constructor(
        public alterEgo: string,
        public age: number,
        public realName: string,
        public person: Person // Inyección por composición
    ) {}
}

const tony = new Person('Tony', 'Stark', 'New York');
const ironman = new Hero('Ironman', 45, 'Tony', tony);

console.log(ironman);

export {};
</code></pre> <p>Por qué este concepto define tu futuro en Angular</p> <p>Si la clase <code>Person</code> cambia mañana (por ejemplo, exige un nuevo parámetro obligatorio en su constructor), la clase <code>Hero</code> por herencia se romperá inmediatamente. Con composición, <code>Hero</code> simplemente recibe la instancia ya construida sin importar cómo fue creada. Este es el mismo principio tras la Inyección de Dependencias de Angular.</p>

src/topics/09-generics.ts<pre><code>// &lt;T&gt; representa un tipo de dato genérico que se determinará en el momento de la llamada
export function whatsMyType&lt;T&gt;(argument: T): T {
    return argument;
}

// Especificación explícita del genérico
const amIString = whatsMyType&lt;string&gt;('Hola Mundo');
const amINumber = whatsMyType&lt;number&gt;(100);
const amIArray = whatsMyType&lt;number[]&gt;([1, 2, 3, 4, 5]);

// TypeScript sabe exactamente qué métodos tiene cada variable gracias a &lt;T&gt;
console.log(amIString.split(' ')); // Métodos de string disponibles (.split)
console.log(amINumber.toFixed(2)); // Métodos de number disponibles (.toFixed)
console.log(amIArray.join(' - ')); // Métodos de array disponibles (.join)

export {};
</code></pre>

src/topics/11-optional-chaining.ts<pre><code>export interface Passenger {
    name: string;
    children?: string[]; // Propiedad opcional
}

const passenger1: Passenger = {
    name: 'Fernando',
};

const passenger2: Passenger = {
    name: 'Melissa',
    children: ['Natalia', 'Elizabeth'],
};

const returnChildrenNumber = (passenger: Passenger): number =&gt; {
    // Si passenger.children es undefined, ?. detiene la evaluación y retorna undefined
    // El operador ?? (Nullish Coalescing) asigna 0 si el resultado es null o undefined
    const howManyChildren = passenger.children?.length ?? 0;

    console.log(`${passenger.name} tiene ${howManyChildren} hijos.`);
    return howManyChildren;
};

returnChildrenNumber(passenger1); // Fernando tiene 0 hijos.
returnChildrenNumber(passenger2); // Melissa tiene 2 hijos.

export {};
</code></pre>

src/app/pages/hero/hero-page.component.tssrc/app/pages/hero/hero-page.component.html src/app/pages/hero/hero-page.component.ts<pre><code>import { Component, computed, signal } from '@angular/core';
import { UpperCasePipe } from '@angular/common';

@Component({
  templateUrl: './hero-page.component.html',
  imports: [UpperCasePipe], // Importación obligatoria para usar | uppercase en el HTML
})
export class HeroPageComponent {
  name = signal('Ironman');
  age = signal(45);

  // Señal computada derivada
  heroDescription = computed(() =&gt; {
    return `${this.name()} - ${this.age()}`;
  });

  // Señal computada para mayúsculas
  capitalizedName = computed(() =&gt; this.name().toUpperCase());

  changeHero() {
    this.name.set('Spiderman');
    this.age.set(22);
  }

  changeAge() {
    this.age.set(60);
  }

  resetForm() {
    this.name.set('Ironman');
    this.age.set(45);
  }
}
</code></pre> src/app/pages/hero/hero-page.component.html<pre><code>&lt;h1&gt;{{ name() }}&lt;/h1&gt;

