@Directive({
  selector: '[appRipple]',
})
export class RippleDirective {
  private el = inject(ElementRef);
  rippleActivado = output&lt;void&gt;();

  @HostListener('click', ['$event'])
  animar(evento: MouseEvent): void {
    const elemento = this.el.nativeElement;
    elemento.classList.add('efecto-ripple-activo');

    setTimeout(() =&gt; {
