tabs.component.tstabs.component.htmltabs.component.csstab.component.ts <pre><code>import { Component, ContentChildren, QueryList, signal, AfterContentInit } from '@angular/core';
import { TabComponent } from './tab.component';

@Component({
  selector: 'app-tabs',
  imports: [TabComponent],
  templateUrl: './tabs.component.html',
  styleUrl: './tabs.component.css'
})
export class TabsComponent implements AfterContentInit {
  @ContentChildren(TabComponent) tabs!: QueryList&lt;TabComponent&gt;;
  tabActivo = signal(0);

  ngAfterContentInit(): void {
    // Activar la primera pestaña por defecto
    this.activarTab(0);
  }

  activarTab(indice: number): void {
    this.tabActivo.set(indice);
    this.tabs.forEach((tab, i) =&gt; {
      tab.activo = i === indice;
    });
  }
}
