formulario-contacto.component.tsformulario-contacto.component.htmlformulario-contacto.component.css <pre><code>import { Component, viewChild, ElementRef, afterNextRender, inject } from '@angular/core';
import { FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'app-formulario-contacto',
  imports: [ReactiveFormsModule],
  templateUrl: './formulario-contacto.component.html',
  styleUrl: './formulario-contacto.component.css'
})
export class FormularioContactoComponent {
  private fb = inject(FormBuilder);

  // View Query para enfocar el primer campo automáticamente
  inputNombre = viewChild.required&lt;ElementRef&lt;HTMLInputElement&gt;&gt;('inputNombre');

  formulario = this.fb.group({
    nombre: ['', [Validators.required, Validators.minLength(3)]],
    email: ['', [Validators.required, Validators.email]],
    asunto: [''],
    mensaje: ['', [Validators.required, Validators.minLength(10)]]
  });

  enviando = false;

  constructor() {
    // Enfocar el input después de que el DOM esté disponible
    afterNextRender(() =&gt; {
      this.inputNombre().nativeElement.focus();
    });
  }

  enviar(): void {
    if (this.formulario.invalid) return;
    this.enviando = true;

    // Simulación de envío
    setTimeout(() =&gt; {
      this.enviando = false;
      console.log('Formulario enviado:', this.formulario.value);
      this.formulario.reset();
      // Volver a enfocar el primer campo tras enviar
      this.inputNombre().nativeElement.focus();
    }, 1500);
  }
}
